// Standalone forward propagation (runs in ~35 microseconds on ESP32)
inline void predict_probabilities(const float standardized_input[7], float output_probs[4]) {
    float h1[32];
    for (int i = 0; i < 32; i++) {
        float sum = B1[i];
        for (int j = 0; j < 7; j++) {
            sum += W1[i][j] * standardized_input[j];
        }
        h1[i] = sum > 0.0f ? sum : 0.0f; // ReLU
    }

    float h2[16];
    for (int i = 0; i < 16; i++) {
        float sum = B2[i];
        for (int j = 0; j < 32; j++) {
            sum += W2[i][j] * h1[j];
        }
        h2[i] = sum > 0.0f ? sum : 0.0f; // ReLU
    }

    float logits[4];
    float max_logit = -1e9f;
    for (int i = 0; i < 4; i++) {
        float sum = B3[i];
        for (int j = 0; j < 16; j++) {
            sum += W3[i][j] * h2[j];
        }
        logits[i] = sum;
        if (sum > max_logit) max_logit = sum;
    }

    // Softmax with numerical stability
    float sum_exp = 0.0f;
    for (int i = 0; i < 4; i++) {
        output_probs[i] = expf(logits[i] - max_logit);
        sum_exp += output_probs[i];
    }
    float inv_sum = 1.0f / sum_exp;
    for (int i = 0; i < 4; i++) {
        output_probs[i] *= inv_sum;
    }
}

